    39			if ((rotation < 0f && p.rotation >= 0f) || (rotation > 0f && p.rotation <= 0f))
    40			{
    41				p.traj.X = 0f;
    42				p.traj.Y -= 50f;
    43				p.rDir = 0f;
    44			}
    45			base.Update(p, frameTime);
    46			if (frame > 0.3f && p.frame <= 0.3f && p.exists && Rand.CoinToss(0.06f))
    47			{
    48				if (p.aux >= 100)
    49				{
    50					ParticleManager.AddAdditiveParticle(121, p.loc, Rand.GetRandomVec2(-10f, 100f, -300f, -200f) * 0.5f, Rand.GetRandomFloat(0.1f, 0.3f), Rand.GetRandomFloat(-1f, 1f), 0, 0);
    51				}
