    61			if (p.aux >= 200 && p.frame > 0.45f)
    62			{
    63				p.frame = Rand.GetRandomFloat(0.4f, 0.45f);
    64			}
    65			float num = 0.5f - p.frame;
    66			float randomFloat = Rand.GetRandomFloat(0.3f, 0.35f);
    67			if (num > 0f && num < randomFloat)
    68			{
    69				Vector2 loc = p.loc;
    70				float num2 = num;
    71				num2 = ((!(num < 0.12f)) ? 1f : (num2 / 0.12f));
    72				num2 *= (0.5f - num) * 2f;
    73				float num3 = 1f;
    74				float num4 = 1f;
    75				if (p.frame < 0.4f)
    76				{
