    39					p.traj.Y -= frameTime * 100f;
    40				}
    41				p.rotation += p.rDir * frameTime;
    42			}
    43			base.Update(p, frameTime);
    44			if (p.exists && p.grounded && (int)(p.frame * 10f) != (int)(frame * 10f))
    45			{
    46				ParticleManager.AddBackAdditiveParticle(109, p.loc, p.traj * Rand.GetRandomFloat(0f, 0.1f), Rand.GetRandomFloat(0f, 0.2f), p.rotation, p.aux, p.owner);
